mapper.select:
select count(1)
from sys_comment
where comment_id = #{parentId}
  and episode_id = #{episodeId}
  and status = 1

mapper.update:
update sys_episode
set comment_count = comment_count + 1
where episode_id = #{episodeId}

update sys_comment
set reply_count = reply_count + 1
where comment_id = #{parentId}
